def endpoint(base_url, path):
    base = base_url.rstrip('/')

    # Normalize any existing trailing /v1 (with or without a slash) away so we
    # can insert exactly one /v1 before the resource. This leaves other version
    # segments such as /v10 untouched.
    if base.endswith('/v1'):
        base = base[: -len('/v1')]

    return base + '/v1/' + path.lstrip('/')

