def admit(active, waiting, budget, slots):
    # A single reservation that alone exceeds the total budget can never be
    # admitted, so reject it even if FIFO processing would stop earlier.
    for value in waiting:
        if value > budget:
            raise ValueError('reservation exceeds the total budget')

    admitted = []
    for value in waiting:
        # The slot count is a total capacity shared with the already-active
        # reservations, so they also count against it.
        fits_budget = sum(active) + sum(admitted) + value <= budget
        fits_slots = len(active) + len(admitted) < slots
        if fits_budget and fits_slots:
            admitted.append(value)
        else:
            # FIFO: stop at the first reservation that fits neither the budget
            # nor the remaining slots; do not skip past it.
            break

    return admitted, waiting[len(admitted):]

